-- Desfaz kids-story-novembro-hd.sql: o perfume volta aos quadros hq-*.webp; Davi, Levi e Marta e Maria voltam aos desenhos em SVG.
\set ON_ERROR_STOP on
BEGIN;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text ~ '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-[1-4]\.webp';
  IF n <> 15 THEN RAISE EXCEPTION 'a-mulher-e-o-perfume: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text ~ '/ilustracoes/davi-e-a-arca/quadros/hd-[1-4]\.webp';
  IF n <> 15 THEN RAISE EXCEPTION 'davi-e-a-arca: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text ~ '/ilustracoes/levi-e-o-banquete/quadros/hd-[1-4]\.webp';
  IF n <> 15 THEN RAISE EXCEPTION 'levi-e-o-banquete: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text ~ '/ilustracoes/marta-e-maria/quadros/hd-[1-4]\.webp';
  IF n <> 15 THEN RAISE EXCEPTION 'marta-e-maria: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
END $$;
UPDATE devotional_kids SET story = (replace(replace(replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-1.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-1.webp'), '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-2.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-2.webp'), '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-4.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-4.webp'))::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-1.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-1.webp'), '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-2.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-2.webp'), '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-3.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-3.webp'), '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-4.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-4.webp'))::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-1.webp', '/ilustracoes/a-mulher-e-o-perfume/quadros/hq-1.webp'))::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(story::text, '/ilustracoes/davi-e-a-arca/quadros/hd-1.webp', '/ilustracoes/davi-e-a-arca/quadros/4-6-1.svg'), '/ilustracoes/davi-e-a-arca/quadros/hd-3.webp', '/ilustracoes/davi-e-a-arca/quadros/4-6-2.svg'), '/ilustracoes/davi-e-a-arca/quadros/hd-4.webp', '/ilustracoes/davi-e-a-arca/quadros/4-6-3.svg'))::jsonb WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it');
