UPDATE devotional_kids SET story = (replace(story::text, '/ilustracoes/davi-e-a-arca/quadros/hd-4.webp', '/ilustracoes/davi-e-a-arca/quadros/11-13-cena.svg'))::jsonb WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-1.webp', '/ilustracoes/levi-e-o-banquete/quadros/4-6-1.svg'), '/ilustracoes/levi-e-o-banquete/quadros/hd-3.webp', '/ilustracoes/levi-e-o-banquete/quadros/4-6-2.svg'), '/ilustracoes/levi-e-o-banquete/quadros/hd-4.webp', '/ilustracoes/levi-e-o-banquete/quadros/4-6-3.svg'))::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-1.webp', '/ilustracoes/levi-e-o-banquete/quadros/7-10-1.svg'), '/ilustracoes/levi-e-o-banquete/quadros/hd-2.webp', '/ilustracoes/levi-e-o-banquete/quadros/7-10-2.svg'), '/ilustracoes/levi-e-o-banquete/quadros/hd-3.webp', '/ilustracoes/levi-e-o-banquete/quadros/7-10-3.svg'), '/ilustracoes/levi-e-o-banquete/quadros/hd-4.webp', '/ilustracoes/levi-e-o-banquete/quadros/7-10-4.svg'))::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-4.webp', '/ilustracoes/levi-e-o-banquete/quadros/11-13-cena.svg'))::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(story::text, '/ilustracoes/marta-e-maria/quadros/hd-1.webp', '/ilustracoes/marta-e-maria/quadros/4-6-1.svg'), '/ilustracoes/marta-e-maria/quadros/hd-2.webp', '/ilustracoes/marta-e-maria/quadros/4-6-2.svg'), '/ilustracoes/marta-e-maria/quadros/hd-4.webp', '/ilustracoes/marta-e-maria/quadros/4-6-3.svg'))::jsonb WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(replace(replace(replace(story::text, '/ilustracoes/marta-e-maria/quadros/hd-1.webp', '/ilustracoes/marta-e-maria/quadros/7-10-1.svg'), '/ilustracoes/marta-e-maria/quadros/hd-2.webp', '/ilustracoes/marta-e-maria/quadros/7-10-2.svg'), '/ilustracoes/marta-e-maria/quadros/hd-3.webp', '/ilustracoes/marta-e-maria/quadros/7-10-3.svg'), '/ilustracoes/marta-e-maria/quadros/hd-4.webp', '/ilustracoes/marta-e-maria/quadros/7-10-4.svg'))::jsonb WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it');
UPDATE devotional_kids SET story = (replace(story::text, '/ilustracoes/marta-e-maria/quadros/hd-2.webp', '/ilustracoes/marta-e-maria/quadros/11-13-cena.svg'))::jsonb WHERE devotional_id = 'cmvyv3ozp003ho72lezbf5h9r' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it');
SELECT devotional_id, count(*) AS versoes, bool_and(story::text NOT LIKE '%hd-%') AS arte_ok
  FROM devotional_kids WHERE devotional_id IN ('cmvyun7rw0032o72lmlzc68bk','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvyv3ozp003ho72lezbf5h9r') AND language IN ('pt-BR','en','es','fr','it') AND story IS NOT NULL GROUP BY devotional_id ORDER BY devotional_id;
COMMIT;
